-- Each fixture and action rolls back through the final pass exception.
DO $$
DECLARE admin_id uuid:=gen_random_uuid(); head_id uuid:=gen_random_uuid(); owner_id uuid:=gen_random_uuid(); other_owner uuid:=gen_random_uuid(); c uuid:=gen_random_uuid(); cp uuid; pipeline uuid; definition uuid; report uuid; mapping uuid; fetched uuid; n int:=0; j jsonb; baseline_id uuid;
BEGIN
 INSERT INTO auth.users(id,instance_id,aud,role,email,raw_user_meta_data,created_at,updated_at) SELECT id,'00000000-0000-0000-0000-000000000000','authenticated','authenticated',email,'{}',now(),now() FROM(VALUES(admin_id,'q50-admin@test.local'),(head_id,'q50-head@test.local'),(owner_id,'q50-owner@test.local'),(other_owner,'q50-other@test.local'))v(id,email);
 UPDATE profiles SET status='active',must_change_password=false WHERE id IN(admin_id,head_id,owner_id,other_owner);
 DELETE FROM user_roles WHERE user_id IN(admin_id,head_id,owner_id,other_owner);
 INSERT INTO user_roles(user_id,role) VALUES(admin_id,'admin'),(head_id,'pipeline_manager'),(owner_id,'client'),(other_owner,'client');
 INSERT INTO clients(id,hotel_name,is_test,is_demo)VALUES(c,'Q50 rollback hotel',false,false); UPDATE profiles SET client_id=c WHERE id=owner_id;
 SELECT id INTO pipeline FROM pipelines WHERE code='social_media';
 INSERT INTO client_pipelines(client_id,pipeline_id,manager_id,status,start_date)VALUES(c,pipeline,head_id,'active','2026-08-20')RETURNING id INTO cp;
 INSERT INTO kpi_definitions(pipeline_id,name,kpi_type,direction,active)VALUES(pipeline,'Q50 isolated numeric KPI','number','higher_better',true)RETURNING id INTO definition;
 INSERT INTO client_kpi_targets(client_pipeline_id,kpi_definition_id,month,target,status)VALUES(cp,definition,'2026-08-01',100,'approved'),(cp,definition,'2026-09-01',100,'approved');
 PERFORM set_config('request.jwt.claims',json_build_object('sub',head_id,'role','authenticated')::text,true);
 PERFORM save_pipeline_baseline(cp,'2026-08-01',jsonb_build_object(definition::text,10),true,NULL);
 IF (SELECT status FROM pipeline_baselines WHERE client_pipeline_id=cp)<>'submitted' THEN RAISE EXCEPTION 'Head baseline submit';END IF;n:=n+1;
 BEGIN PERFORM approve_pipeline_baseline(cp);RAISE EXCEPTION 'Head approved baseline';EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Only Management%' THEN RAISE;END IF;END;n:=n+1;
 PERFORM set_config('request.jwt.claims',json_build_object('sub',admin_id,'role','authenticated')::text,true);PERFORM approve_pipeline_baseline(cp);
 IF NOT EXISTS(SELECT 1 FROM pipeline_baselines WHERE client_pipeline_id=cp AND status='approved' AND approved_by=admin_id)THEN RAISE EXCEPTION 'Baseline approval';END IF;n:=n+1;
 PERFORM set_config('request.jwt.claims',json_build_object('sub',head_id,'role','authenticated')::text,true);
 BEGIN PERFORM save_pipeline_baseline(cp,'2026-08-01',jsonb_build_object(definition::text,20),false,'head change');RAISE EXCEPTION 'Head changed approved baseline';EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Approved baseline%' THEN RAISE;END IF;END;n:=n+1;
 PERFORM set_config('request.jwt.claims',json_build_object('sub',admin_id,'role','authenticated')::text,true);PERFORM save_pipeline_baseline(cp,'2026-08-01',jsonb_build_object(definition::text,11),false,'Correct source');
 SELECT id INTO baseline_id FROM pipeline_baselines WHERE client_pipeline_id=cp;
 IF NOT EXISTS(SELECT 1 FROM admin_audit_log WHERE actor=admin_id AND target_id=baseline_id::text AND details->>'reason'='Correct source')THEN RAISE EXCEPTION 'Baseline audit missing';END IF;n:=n+1;
 j:=kpi_backentry_progress('2026-11-05');IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(j)x WHERE x->>'id'=cp::text AND x->>'months_required'='3' AND x->>'deadline'='2026-11-05')THEN RAISE EXCEPTION 'Backentry required months/deadline';END IF;n:=n+1;
 IF NOT q57_review_open('2026-10-01','2026-10-31T18:30:00Z') OR q57_review_open('2026-10-01','2026-11-03T18:30:00Z') THEN RAISE EXCEPTION 'IST review window';END IF;n:=n+1;
 mapping:=confirm_kpi_mapping('metricool','q50-test-external','Q50 hotel',cp);
 IF NOT EXISTS(SELECT 1 FROM kpi_source_mappings WHERE id=mapping AND confirmed_by=admin_id)THEN RAISE EXCEPTION 'Confirmed mapping';END IF;n:=n+1;
 INSERT INTO kpi_fetched_values(mapping_id,client_pipeline_id,month,source,fetched_values)VALUES(mapping,cp,'2026-09-01','metricool','{"instagram.posts":5}')RETURNING id INTO fetched;
 BEGIN UPDATE kpi_fetched_values SET fetched_values='{"instagram.posts":6}' WHERE id=fetched;RAISE EXCEPTION 'Provenance changed';EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Fetched source provenance%'THEN RAISE;END IF;END;n:=n+1;
 BEGIN PERFORM approve_fetched_kpis(fetched);RAISE EXCEPTION 'Unconfirmed approved';EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Pipeline head confirmation%'THEN RAISE;END IF;END;n:=n+1;
 UPDATE kpi_fetched_values SET corrected_values='{"instagram.posts":4}',corrected_by=head_id,confirmed_by=head_id,confirmed_at=now(),status='confirmed' WHERE id=fetched;
 PERFORM approve_fetched_kpis(fetched);
 IF NOT EXISTS(SELECT 1 FROM kpi_fetched_values WHERE id=fetched AND fetched_values->>'instagram.posts'='5' AND corrected_values->>'instagram.posts'='4' AND approved_by=admin_id AND status='approved')THEN RAISE EXCEPTION 'Fetched/corrected/approved retention';END IF;n:=n+1;
 INSERT INTO monthly_reports(client_id,client_pipeline_id,month,status,highlights,challenges,manager_comments)VALUES(c,cp,'2026-09-01','approved',ARRAY['Approved highlight'],'SECRET INTERNAL','SECRET MANAGEMENT')RETURNING id INTO report;
 INSERT INTO kpi_entries(report_id,kpi_definition_id,target,actual,target_status)VALUES(report,definition,100,60,'approved');
 PERFORM set_config('request.jwt.claims',json_build_object('sub',owner_id,'role','authenticated')::text,true);j:=combined_monthly_report(c,'2026-09-01');
 IF jsonb_array_length(j->'sections')<>1 OR j::text LIKE '%SECRET%' THEN RAISE EXCEPTION 'Combined report private scope';END IF;n:=n+1;
 IF j->'sections'->0->'kpis'->0->>'baseline'<>'11' THEN RAISE EXCEPTION 'Approved baseline comparison';END IF;n:=n+1;
 IF j->'sections'->0->'source_values'->0->'values'->>'instagram.posts'<>'4' THEN RAISE EXCEPTION 'Approved corrected source visibility';END IF;n:=n+1;
 PERFORM set_config('request.jwt.claims',json_build_object('sub',other_owner,'role','authenticated')::text,true);
 BEGIN PERFORM combined_monthly_report(c,'2026-09-01');RAISE EXCEPTION 'Other owner scope allowed';EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'Not allowed'THEN RAISE;END IF;END;n:=n+1;
 PERFORM set_config('request.jwt.claims',json_build_object('sub',head_id,'role','authenticated')::text,true);
 BEGIN INSERT INTO monthly_reports(client_id,client_pipeline_id,month,status)VALUES(c,cp,'2026-08-01','approved');RAISE EXCEPTION 'Head report approval allowed';EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Only Management%'THEN RAISE;END IF;END;n:=n+1;
 PERFORM set_config('request.jwt.claims',json_build_object('sub',admin_id,'role','authenticated')::text,true);
 j:=portfolio_report_health('2026-09-01');IF EXISTS(SELECT 1 FROM jsonb_array_elements(j->'at_risk')x WHERE x->>'id'=c::text)THEN RAISE EXCEPTION 'Missing prior month became red';END IF;n:=n+1;
 INSERT INTO monthly_reports(client_id,client_pipeline_id,month,status)VALUES(c,cp,'2026-08-01','approved')RETURNING id INTO report;INSERT INTO kpi_entries(report_id,kpi_definition_id,target,actual,target_status)VALUES(report,definition,100,60,'approved');
 j:=portfolio_report_health('2026-09-01');IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(j->'at_risk')x WHERE x->>'id'=c::text)THEN RAISE EXCEPTION 'Two red months missing';END IF;n:=n+1;
 IF scorecard_band(90)<>'green' OR scorecard_band(70)<>'amber' OR scorecard_band(69)<>'red'THEN RAISE EXCEPTION 'Bands 90/70';END IF;n:=n+1;
 IF (SELECT value FROM app_settings WHERE key='scorecard_weights')<>'{"kpi":50,"on_time":20,"launch":20,"red_actions":10}'::jsonb THEN RAISE EXCEPTION 'Weights changed';END IF;n:=n+1;
 RAISE EXCEPTION 'Q50 Q57 TESTS PASSED: %/20',n;
END $$;